const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const shanghai = ee.Geometry.Point([121.4737, 31.2304]).buffer(50000); // Shanghai center with 50km buffer

  // Time periods
  const period1_start = '2020-02-10';
  const period1_end = '2020-02-25';
  const period2_start = '2020-04-20';
  const period2_end = '2020-05-12';

  // 2. Data Acquisition
  const no2_col1 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(period1_start, period1_end)
    .filterBounds(shanghai)
    .select('tropospheric_NO2_column_number_density');

  const no2_col2 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(period2_start, period2_end)
    .filterBounds(shanghai)
    .select('tropospheric_NO2_column_number_density');

  // Check collection sizes
  const size1 = no2_col1.size().getInfo();
  const size2 = no2_col2.size().getInfo();

  console.log(`Period 1 (Feb 10-25): ${size1} images`);
  console.log(`Period 2 (Apr 20-May 12): ${size2} images`);

  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Create mean composites
  const mean1 = no2_col1.mean();
  const mean2 = no2_col2.mean();

  // 3. Processing - Check valid pixels
  const count1 = mean1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: shanghai,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  const count2 = mean2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: shanghai,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  console.log(`Valid pixels - Period 1: ${count1}, Period 2: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean NO2 values
  const mean_no2_1 = mean1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: shanghai,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  const mean_no2_2 = mean2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: shanghai,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  console.log(`Mean NO2 - Period 1: ${mean_no2_1?.toFixed(6)} mol/m²`);
  console.log(`Mean NO2 - Period 2: ${mean_no2_2?.toFixed(6)} mol/m²`);

  // 5. Validation & Final Answer
  if (mean_no2_1 === null || mean_no2_2 === null || 
      isNaN(mean_no2_1) || isNaN(mean_no2_2) ||
      mean_no2_1 < 0 || mean_no2_2 < 0) {
    console.log("<answer>C3</answer>");
  } else if (mean_no2_2 > mean_no2_1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
